// Normalisation de l'entree du webhook. Deux modes :
//  - nouvelle  : Lineo valide une offre dans career-ops -> nouvelle branche cv/*
//  - retouche  : le workflow 3 renvoie la meme candidature avec une consigne
//                -> on REUTILISE la branche, sinon le round precedent est perdu
//
// Le declencheur est lu par son NOM, pas par $json : le predecesseur immediat
// est le noeud Config, et $json y renverrait la configuration au lieu de l'offre.
const cfg = $('⚙️ Config').first().json;
const brut = $('🔔 Webhook: generer la candidature').first().json ?? {};
const recu = brut.body ?? brut;

const mode = String(recu.mode || 'nouvelle').trim().toLowerCase();
const retouche = mode === 'retouche';

const job = recu.job ?? recu.offre ?? {};
const slug = (v) => String(v || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '').slice(0, 40);

const titre = String(job.title ?? job.poste ?? '').trim();
const entreprise = String(job.company ?? job.entreprise ?? '').trim();
const description = String(job.description ?? '').trim();

// Sans intitule NI description, /api/letter refusera de toute facon : on echoue
// ici, ou le message est lisible, plutot que dans un 400 au milieu de la chaine.
if (!titre && !description) {
  throw new Error('offre inexploitable : ni title ni description. Recu : ' + JSON.stringify(recu).slice(0, 300));
}

// France Travail rend souvent le lieu comme OBJET : sans coercition, l'app
// afficherait « [object Object] ».
const lieuBrut = job.location ?? job.lieu;
let lieu = null;
if (typeof lieuBrut === 'string') lieu = lieuBrut.trim() || null;
else if (lieuBrut && typeof lieuBrut === 'object') {
  lieu = lieuBrut.libelle || lieuBrut.nom || lieuBrut.ville || lieuBrut.label || lieuBrut.name
    || Object.values(lieuBrut).filter((v) => typeof v === 'string' && v.trim()).join(', ') || null;
}

const jobId = String(job.jobId ?? job.id ?? '').trim();
const inboxId = retouche
  ? String(recu.ficheId || '').trim()
  : (slug(jobId) || slug(entreprise + '-' + titre) || 'sans-id');
if (!inboxId) throw new Error('retouche sans ficheId : impossible de savoir quelle fiche mettre a jour');

// La branche est la CLE NATURELLE de la candidature (contrainte UNIQUE en base).
// En retouche elle vient de l'appelant ; sinon on la derive de l'execution.
const suffixe = String($execution.id || Date.now()).slice(-8);
const branchName = retouche
  ? String(recu.branche || '').trim()
  : 'cv/' + (slug(entreprise) || 'entreprise') + '-' + (slug(titre) || 'poste') + '-' + suffixe;
if (!branchName) throw new Error('retouche sans branche : la candidature serait dupliquee sur une branche neuve');

const cible = String(recu.cible || '').trim().toLowerCase();
const consigne = String(recu.consigne || '').trim().slice(0, 600);

return [{
  json: {
    mode, retouche, inboxId, branchName, jobId,
    // La consigne ne part QUE vers la piece que Lineo a demande de retoucher :
    // retoucher la lettre ne doit pas remuer le CV, et inversement.
    consigneLettre: retouche && cible !== 'cv' ? consigne : '',
    consigneCv: retouche && cible === 'cv' ? consigne : '',
    cibleRetouche: cible,
    offre: { title: titre, company: entreprise, location: lieu, url: String(job.url ?? job.url_offre ?? '').trim(), description, whyMatch: String(job.whyMatch ?? job.pourquoi_ca_matche ?? '').trim() },
    courrielContact: String(job.contactEmail ?? job.courriel_contact ?? '').trim(),
    score: job.score ?? null,
    repository: cfg.githubOwner + '/' + cfg.githubRepo,
    baseBranch: cfg.githubBaseBranch,
    filePath: cfg.githubLocaleFilePath,
    letterPath: cfg.githubLetterFilePath,
    inboxPath: 'data-inbox/' + inboxId + '.json',
    nowIso: new Date().toISOString(),
    cleRun: (slug(entreprise) || 'entreprise') + '-' + (slug(titre) || 'poste') + '-' + suffixe,
  },
}];

// letters/current.yml, le fichier que tools/build_letter.py rend en DOCX une page.
// Le texte vient de /api/letter, deja nettoye la-bas (ni tiret cadratin, ni
// markdown, ni anciennete inventee) : on ne refait pas ce travail, on met en forme.
//
// [skip ci] DANS LE MESSAGE DE COMMIT, ET C'EST STRUCTUREL :
// build-and-commit-pdfs.yml declare concurrency: cancel-in-progress sur la
// branche. Sans [skip ci], le push de la lettre lance un run que le push du CV
// annule aussitot, et les deux runs peuvent se cancelliser mutuellement (constate
// le 06/08 : runs 31108490726 et 31108491527, tous deux annules, zero PDF).
// Une candidature = un seul run d'Action, celui du CV, qui arrive en dernier.
const cfg = $('⚙️ Config').first().json;
const ctx = $('🧩 Contexte candidature').first().json;
const lettre = $('🌐 career-ops: lettre').first().json ?? {};
const file = $json ?? {};

const q = (v) => JSON.stringify(String(v ?? '').replace(/\s+/g, ' ').trim());

const paras = String(lettre.letter_body || '')
  .split(/\n\s*\n/)
  .map((p) => p.split('\n').map((l) => l.trim()).filter(Boolean).join(' '))
  .map((p) => p.replace(/\s+/g, ' ').trim())
  .filter(Boolean);

if (paras.length === 0) {
  throw new Error('lettre vide apres mise en forme : rien ne doit etre commite ni envoye');
}

const mots = paras.join(' ').split(/\s+/).filter(Boolean).length;
const bodyBlock = paras.map((p) => '    ' + p).join('\n\n');
const today = new Date().toISOString().slice(0, 10);
const locale = cfg.targetLanguage || 'fr';
const closing = locale === 'en'
  ? 'Kind regards,'
  : "Je vous prie d'agreer, Madame, Monsieur, l'expression de mes salutations distinguees.";

const yamlText = [
  'meta:',
  '  locale: ' + q(locale),
  '  generated_at: ' + q(today),
  'sender:',
  '  name: ' + q(cfg.candidateName),
  '  title: ' + q('Ingénieur en automatisation & intégration IA'),
  '  email: ' + q(cfg.candidateEmail),
  '  phone: ' + q(cfg.candidatePhone),
  '  location: ' + q('Nogent-sur-Marne (94)'),
  'target:',
  '  company: ' + q(ctx.offre.company),
  '  job_title: ' + q(ctx.offre.title),
  '  job_url: ' + q(ctx.offre.url),
  '  recipient: ' + q(lettre.salutation || 'Madame, Monsieur,'),
  '  city: ' + q('Nogent-sur-Marne'),
  'letter:',
  '  subject: ' + q(lettre.email_subject || ''),
  '  body: |',
  bodyBlock,
  '  closing: ' + q(closing),
  '',
].join('\n');

const bodyObj = {
  message: 'chore(letter): lettre ' + (ctx.offre.company || 'candidature') + ' - ' + (ctx.offre.title || 'poste') + ' [skip ci]',
  content: Buffer.from(yamlText, 'utf8').toString('base64'),
  branch: ctx.branchName,
};
if (file.sha) bodyObj.sha = file.sha;

return [{ json: { ...ctx, letterWords: mots, letterTooLong: mots > 470, letterBodyRaw: JSON.stringify(bodyObj) } }];

const file = $json;
const ctx = $('🧩 Contexte candidature').first().json;
const originalYaml = Buffer.from(String(file.content || '').replace(/\n/g, ''), 'base64').toString('utf8');

if (!originalYaml.trim()) {
  throw new Error('locales/fr.yml illisible sur la branche ' + ctx.branchName + ' : adaptation impossible');
}

return [{ json: { ...ctx, previousFileSha: file.sha, originalYaml, originalCharCount: originalYaml.length } }];

// Contrat gele : POST /api/tailor -> { keywords: string[], titre? }
// Indisponible ou vide -> keywordsSource = 'mode', et c'est la regle ATS de
// modes/pdf.md qui tranchera cote career-ops. Le repli est explicite, jamais muet.
const prep = $('🧩 Contexte CV YAML').first().json;
const rep = $input.first().json ?? {};

const keywords = (Array.isArray(rep.keywords) ? rep.keywords : [])
  .map((k) => String(k || '').trim())
  .filter((k) => k.length > 0 && k.length <= 60)
  .filter((k, i, tout) => tout.indexOf(k) === i)
  .slice(0, 12);

return [{
  json: {
    ...prep,
    keywords,
    keywordsSource: keywords.length > 0 ? 'api' : 'mode',
    titreImpose: String(rep.titre || '').trim(),
  },
  pairedItem: 0,
}];

// /api/run rend du NDJSON : un objet JSON par ligne. Le seul evenement qui
// compte est { type: 'artifact', adaptedYaml } — la route ne l'emet qu'apres
// avoir verifie qu'aucune cle n'a saute, qu'aucune date n'a bouge, qu'aucune
// anciennete n'a ete inventee et que le volume est plausible.
const prep = $('🧩 Mots-cles ou repli').first().json;
const brut = String($json.flux ?? $json.data ?? '');

let adaptedYaml = '';
const erreurs = [];
for (const ligne of brut.split('\n')) {
  const t = ligne.trim();
  if (!t) continue;
  let ev;
  try { ev = JSON.parse(t); } catch (e) { continue; }
  if (ev && ev.type === 'artifact' && typeof ev.adaptedYaml === 'string') adaptedYaml = ev.adaptedYaml;
  if (ev && ev.type === 'error' && ev.msg) erreurs.push(String(ev.msg));
}

// Le corps peut aussi etre une erreur JSON simple (400/500 avant le flux).
if (!adaptedYaml && !erreurs.length) {
  try {
    const j = JSON.parse(brut);
    if (j && j.error) erreurs.push(String(j.error));
  } catch (e) { /* ce n'etait pas du JSON : le flux parle deja */ }
}

const cvAdapte = adaptedYaml.trim().length > 0;
const cvMotif = cvAdapte
  ? ''
  : (erreurs.join(' | ') || "le skill n'a rendu aucun CV adapte").slice(0, 400);

return [{ json: { ...prep, adaptedYaml, cvAdapte, cvMotif }, pairedItem: 0 }];

const payload = $('🧩 Contexte CV YAML').first().json;
const tailor = $('🧩 Mots-cles ou repli').first().json;
const adaptedYaml = String($json.adaptedYaml ?? '').trim();
const originalYaml = String(payload.originalYaml || '');
const source = adaptedYaml.length > 0 ? adaptedYaml : originalYaml;

// L'API contents rend le blob, donc du LF (.gitattributes : text=auto eol=lf).
// On reste agnostique et on recolle avec la fin de ligne DOMINANTE, pour ne
// jamais fabriquer un fichier a fins de ligne melangees.
const eol = (source.match(/\r\n/g) || []).length > (source.match(/(?<!\r)\n/g) || []).length ? '\r\n' : '\n';
const lignesOrig = originalYaml.split(/\r?\n/);

// GARDE-FOU 1 : scalaires plain dangereux. Run 958225 : « Ma methode : fiabiliser »
// rendu sur une seule ligne -> typst refuse le fichier, Action en echec, zero PDF.
const risque = (v) => !/^[>|[{'"&*!]/.test(v) && (/:\s/.test(v) || /\s#/.test(v));
let lignes = source.split(/\r?\n/).map((l) => {
  let m = l.match(/^(\s*(?:- )?)([A-Za-z_][A-Za-z0-9_-]*): (.+?)\s*$/);
  if (m && risque(m[3])) return m[1] + m[2] + ': ' + JSON.stringify(m[3]);
  m = l.match(/^(\s*- )(?![A-Za-z_][A-Za-z0-9_-]*: )(.+?)\s*$/);
  if (m && risque(m[2])) return m[1] + JSON.stringify(m[2]);
  return l;
});

function keywordsDe(lignesSrc) {
  const j = lignesSrc.findIndex((l) => /^keywords\s*:/.test(l));
  if (j === -1) return [];
  const reste = lignesSrc[j].replace(/^keywords\s*:/, '').trim();
  if (reste.startsWith('[')) {
    try { const v = JSON.parse(reste); return Array.isArray(v) ? v.map(String) : []; } catch (e) { return []; }
  }
  const out = [];
  for (let k = j + 1; k < lignesSrc.length && /^\s+\S/.test(lignesSrc[k]); k++) {
    const m = lignesSrc[k].match(/^\s+-\s+(.+?)\s*$/);
    if (!m) continue;
    let v = m[1].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
      try { v = JSON.parse(v.replace(/^'|'$/g, '"')); } catch (e) { v = v.slice(1, -1); }
    }
    out.push(String(v));
  }
  return out;
}

const utiliseApi = tailor.keywordsSource === 'api' && Array.isArray(tailor.keywords) && tailor.keywords.length > 0;
const mots = utiliseApi ? tailor.keywords : keywordsDe(lignesOrig);
const ligneKeywords = 'keywords: [' + mots.map((m) => JSON.stringify(String(m))).join(', ') + ']';

// GARDE-FOU 2 : quand /api/tailor a repondu, c'est SA liste qui fait foi. Et si
// la cle keywords a ete supprimee en amont, on la restaure : sans elle, la
// section ATS « Competences cles » disparait du PDF.
const iKw = lignes.findIndex((l) => /^keywords\s*:/.test(l));
let keywordsInjectes = false;
const keywordsRestaures = iKw === -1;

if (iKw !== -1) {
  if (utiliseApi) {
    let j = iKw + 1;
    while (j < lignes.length && /^\s+\S/.test(lignes[j])) j++;
    lignes = [...lignes.slice(0, iKw), ligneKeywords, ...lignes.slice(j)];
    keywordsInjectes = true;
  }
} else {
  let apres = null;
  const j = lignesOrig.findIndex((l) => /^keywords\s*:/.test(l));
  for (let k = j + 1; j !== -1 && k < lignesOrig.length; k++) {
    const m = lignesOrig[k].match(/^([A-Za-z_][A-Za-z0-9_-]*)\s*:/);
    if (m) { apres = m[1]; break; }
  }
  const pos = apres ? lignes.findIndex((l) => new RegExp('^' + apres + '\\s*:').test(l)) : -1;
  if (pos !== -1) lignes = [...lignes.slice(0, pos), ligneKeywords, '', ...lignes.slice(pos)];
  else lignes = [...lignes, ligneKeywords];
  keywordsInjectes = utiliseApi;
}

let finalYaml = lignes.join(eol);
if (!finalYaml.endsWith(eol)) finalYaml += eol;

const bodyObj = {
  message: 'chore(cv): CV adapte ' + (payload.offre.company || 'candidature') + ' - ' + (payload.offre.title || 'poste'),
  content: Buffer.from(finalYaml, 'utf8').toString('base64'),
  branch: payload.branchName,
};
if (payload.previousFileSha) bodyObj.sha = payload.previousFileSha;

return [{
  json: {
    ...payload,
    cvAdapte: $json.cvAdapte === true,
    cvMotif: String($json.cvMotif || ''),
    keywordsSource: tailor.keywordsSource,
    keywordsRetenus: mots,
    keywordsInjectes,
    keywordsRestaures,
    cvBodyRaw: JSON.stringify(bodyObj),
  },
}];

// Le commit du CV est le DERNIER push de la branche : c'est lui que l'Action
// « Build and Commit PDFs » va traiter. On garde son sha pour retrouver LE bon
// run, et pas celui d'une autre candidature poussee au meme moment.
const ctx = $('🧩 Construire le CV YAML').first().json;
const cfg = $('⚙️ Config').first().json;
const rep = $json.body ?? $json;

return [{
  json: {
    ...ctx,
    commitSha: rep.commit?.sha || rep.content?.sha || '',
    commitUrl: rep.commit?.html_url || '',
    targetWorkflowName: cfg.githubActionWorkflowName,
    pollAttempt: 0,
    pollIntervalSeconds: Number(cfg.githubActionPollSeconds || 20),
    pollMaxAttempts: Number(cfg.githubActionMaxPollAttempts || 30),
  },
}];

const context = $('⏳ Attendre l\'Action GitHub').item.json;
const runs = Array.isArray($json.workflow_runs) ? $json.workflow_runs : [];
const targetWorkflowName = String(context.targetWorkflowName || 'Build and Commit PDFs');
const commitSha = String(context.commitSha || '').toLowerCase();

// Appariement par nom d'Action ET sha du commit : c'est le seul moyen sur de ne
// pas conclure sur le run d'une AUTRE candidature poussee entre-temps.
let matchingRun = null;
if (commitSha) {
  matchingRun = runs.find((run) =>
    String(run.name || '') === targetWorkflowName &&
    String(run.head_sha || '').toLowerCase() === commitSha);
}
if (!matchingRun) {
  matchingRun = runs.find((run) => String(run.name || '') === targetWorkflowName);
}

const pollAttempt = Number(context.pollAttempt || 0) + 1;
const pollMaxAttempts = Number(context.pollMaxAttempts || 30);
const completed = matchingRun?.status === 'completed' || pollAttempt >= pollMaxAttempts;

return [{
  json: {
    ...context,
    pollAttempt,
    targetWorkflowName,
    runId: matchingRun?.id ?? '',
    runStatus: matchingRun?.status ?? 'not_found',
    runConclusion: matchingRun?.conclusion ?? '',
    runHtmlUrl: matchingRun?.html_url ?? '',
    completed,
    // Depasser le plafond sans run termine n'est PAS un succes : sans ce drapeau,
    // un timeout ressemblerait a une Action qui n'a simplement pas reussi.
    pollEpuise: matchingRun?.status !== 'completed' && pollAttempt >= pollMaxAttempts,
  },
}];

const run = $json;
const motif = run.pollEpuise
  ? "l'Action GitHub n'a pas termine apres " + run.pollAttempt + ' verifications : le CV n a pas pu etre rendu"'
  : "l'Action GitHub s'est terminee en echec (conclusion : " + (run.runConclusion || 'inconnue') + ')';
return [{ json: { ...run, incident: motif } }];

const cfg = $('⚙️ Config').first().json;
const ctx = $('🧩 Statut du run').first().json;
const lettre = $('🌐 career-ops: lettre').first().json ?? {};

const cleanTxt = (s) => String(s || '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/ [—–] /g, ', ').replace(/[—–]/g, ', ');

const repoBase = 'https://github.com/' + cfg.githubOwner + '/' + cfg.githubRepo;
const branch = ctx.branchName;

// La decision remonte au workflow 3 par ce webhook. L'id voyage dans l'URL :
// career-ops POSTe { decision, consigne, raison } SANS id, il ne le connait que
// par la fiche. Sans ce parametre, le workflow 3 ne saurait pas quoi envoyer.
const decisionUrl = String(cfg.decisionWebhook) + '?id=' + encodeURIComponent(ctx.inboxId);

const fiche = {
  schema: 'career-ops-inbox/v2',
  id: ctx.inboxId,
  statut: 'A_VALIDER',
  source: 'n8n/france-travail',
  cree_le: ctx.nowIso,
  execution_id: String($execution.id),
  decision_url: decisionUrl,
  decisions_acceptees: ['valider', 'retoucher_lettre', 'retoucher_cv', 'refuser'],
  // job_id : sans lui, une retouche ne pourrait pas retrouver l'annonce complete
  // dans le journal des offres, et le CV serait readapte sans sa description.
  job_id: ctx.jobId || '',
  poste: ctx.offre.title,
  entreprise: ctx.offre.company,
  lieu: ctx.offre.location,
  url_offre: ctx.offre.url,
  courriel_contact: ctx.courrielContact,
  score: ctx.score,
  pourquoi_ca_matche: cleanTxt(ctx.offre.whyMatch),
  objet_mail: cleanTxt(lettre.email_subject || ''),
  salutation: cleanTxt(lettre.salutation || ''),
  apercu_lettre: cleanTxt(lettre.letter_body || ''),
  arguments_cles: (lettre.key_selling_points || []).map(cleanTxt),
  branche_github: branch,
  cv_pdf: cfg.githubPdfPath,
  lettre_docx: cfg.githubLetterDocxPath,
  cv_url: repoBase + '/blob/' + branch + '/' + cfg.githubPdfPath,
  lettre_url: repoBase + '/blob/' + branch + '/' + cfg.githubLetterDocxPath,
  // Le CV a-t-il vraiment ete adapte, ou est-ce l'original ? Linéo doit le voir
  // avant de valider, pas le decouvrir chez le recruteur.
  cv_adapte: ctx.cvAdapte === true,
  cv_motif: ctx.cvMotif || '',
  mots_cles_source: ctx.keywordsSource || '',
};

return [{ json: { ...ctx, fiche, courrielContact: String(ctx.courrielContact || '').trim() } }];

// Upsert de la fiche. `revision` compte les rounds : career-ops s'en sert pour
// savoir si l'aller-retour d'une retouche est termine (fichesEnAttenteDepuis).
const prep = $('🧩 Preparer la fiche').first().json;
const cfg = $('⚙️ Config').first().json;
const prev = $input.first().json ?? {};

const sha = typeof prev.sha === 'string' && prev.sha ? prev.sha : null;

let revision = 0;
if (sha && typeof prev.content === 'string') {
  try {
    const ancienne = JSON.parse(Buffer.from(prev.content.replace(/\n/g, ''), 'base64').toString('utf8'));
    revision = Number(ancienne.revision || 0) + 1;
  } catch (e) {
    revision = 1;
  }
}

const fiche = { ...prep.fiche, revision };

const body = {
  message: (sha ? 'chore(inbox): maj ' : 'chore(inbox): ') + (fiche.entreprise || 'candidature') + ' - ' + (fiche.poste || 'poste'),
  content: Buffer.from(JSON.stringify(fiche, null, 2) + '\n', 'utf8').toString('base64'),
  branch: cfg.githubBaseBranch,
};
if (sha) body.sha = sha;

return [{ json: { ...prep, fiche, ficheRevision: revision, inboxBodyRaw: JSON.stringify(body) } }];

// Les pieces jointes sont reconstruites depuis les noeuds de telechargement :
// ni Postgres ni l'ecriture GitHub ne transportent le binaire.
const prep = $('🧩 Fiche: corps + sha').first().json;

const bin = {};
try {
  const b = $('📥 Telecharger le CV PDF').first().binary || {};
  if (b.data) bin.data = { ...b.data, fileName: 'cv-BIRIBIN-LINEO.pdf', fileExtension: 'pdf' };
} catch (e) { /* pas de PDF : le chemin d'incident a deja pris la main */ }
try {
  const b = $('📥 Telecharger la lettre DOCX').first().binary || {};
  if (b.docx) bin.docx = { ...b.docx, fileName: 'lettre-BIRIBIN-LINEO.docx', fileExtension: 'docx' };
} catch (e) { /* lettre absente : tolere */ }

const pieces = [];
if (bin.data) pieces.push('CV PDF adapte au poste');
if (bin.docx) pieces.push('lettre de motivation Word (1 page)');

return [{
  json: {
    ...prep,
    attachmentNames: pieces.join(' + '),
    attachmentProps: [bin.data ? 'data' : null, bin.docx ? 'docx' : null].filter(Boolean).join(','),
  },
  binary: bin,
}];
